impl Solution {
    pub fn max_in_table(n: u32) -> u32 {
        if n == 1 {
            return 1;
        }
        let mut table = vec![vec![1; n as usize]; n as usize];
        for i in 1..n {
            for j in 1..n {
                table[i as usize][j as usize] = table[(i-1) as usize][j as usize] + table[i as usize][(j-1) as usize];
            }
        }
        *table.iter().map(|row| row.iter().max().unwrap()).max().unwrap()
    }
}

